"use client";

import { memo, useCallback, useImperativeHandle, useMemo, useRef, useState } from "react";
import type { FocusEvent } from "react";
import { cn } from "@/lib/utils";
import type { VideoPlayerProps, VideoState, VideoTrack } from "./types";
import { createDurationFormatter, resolveLabels, resolveLocale } from "./lib/format";
import { useVideoState } from "./hooks/use-video-state";
import { useDoubleTap } from "./hooks/use-double-tap";
import { useDirection } from "./hooks/use-direction";
import { useFullscreen } from "./hooks/use-fullscreen";
import { useControlsVisibility } from "./hooks/use-controls-visibility";
import { usePrefersReducedMotion, useVisibility } from "./hooks/use-environment";
import { VideoElement } from "./parts/video-element";
import { DefaultControls } from "./parts/default-controls";
import { VideoPlayerContext, type VideoPlayerContextValue } from "./parts/video-player-context";

const NO_TRACKS: VideoTrack[] = [];

function VideoPlayerInner({
  src,
  poster,
  tracks = NO_TRACKS,
  crossOrigin,
  isActive = true,
  loop: loopProp,
  muted = true,
  onMutedChange,
  playsInline = true,
  preload = "metadata",
  autoPlay = false,
  durationHint,
  autoPlayInView = false,
  autoPlayThreshold = 0.5,
  autoplayGroup,
  objectFit = "cover",
  dir: dirProp,
  controls = true,
  renderControls,
  controlsAutoHideMs = 2000,
  showSeekBar = true,
  showTime = true,
  showFullscreen = false,
  seekStep = 5,
  onDoubleTap,
  onPlay,
  onPause,
  onEnded,
  onTimeUpdate,
  onProgress,
  onLoadedMetadata,
  onError,
  onMediaError,
  labels: labelsProp,
  locale: localeProp,
  formatDuration,
  className,
  videoClassName,
  controlsClassName,
  ref,
}: VideoPlayerProps) {
  // `onEnded` with the default `loop` could never fire — the callback asks for a non-looping video.
  const loop = loopProp ?? onEnded === undefined;

  const labels = useMemo(() => resolveLabels(labelsProp), [labelsProp]);
  const locale = useMemo(() => resolveLocale(localeProp), [localeProp]);
  const defaultFormat = useMemo(() => createDurationFormatter(locale), [locale]);
  const formatTime = useCallback(
    (seconds: number) => (formatDuration ? formatDuration(seconds, locale) : defaultFormat(seconds)),
    [formatDuration, locale, defaultFormat],
  );

  const rootRef = useRef<HTMLDivElement>(null);
  const dir = useDirection(rootRef, dirProp);
  const reducedMotion = usePrefersReducedMotion();
  const autoplayOn = autoPlayInView && !reducedMotion;
  const visible = useVisibility(rootRef, autoPlayThreshold, autoplayOn);

  const video = useVideoState({
    src,
    muted,
    onMutedChange,
    isActive,
    tracks,
    autoplayGroup,
    autoPlayInView: autoplayOn,
    visible,
    onPlay,
    onPause,
    onEnded,
    onTimeUpdate,
    onProgress,
    onLoadedMetadata,
    onError,
    onMediaError,
  });
  const { canFullscreen, isFullscreen, toggleFullscreen } = useFullscreen(rootRef, video.videoElRef);
  // Auto-hide pauses while keyboard focus sits on a control or a menu is open (VP6).
  const [focusPinned, setFocusPinned] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const { visible: controlsVisible, wake } = useControlsVisibility(
    video.state.isPlaying,
    controlsAutoHideMs,
    reducedMotion,
    focusPinned || menuOpen,
  );
  const handleFocus = useCallback(
    (e: FocusEvent<HTMLDivElement>) => {
      wake();
      // React types `target` as the handler's element; on a bubbled focus it is any descendant.
      const target = e.target as Element;
      let keyboard = false;
      try {
        keyboard = target.matches(":focus-visible");
      } catch {
        // `:focus-visible` unsupported — treat as pointer focus.
      }
      setFocusPinned(keyboard && target !== video.videoElRef.current);
    },
    [wake, video.videoElRef],
  );
  const handleBlur = useCallback(
    (e: FocusEvent<HTMLDivElement>) => {
      const next = e.relatedTarget;
      if (!(next instanceof Node) || !rootRef.current?.contains(next) || next === video.videoElRef.current) {
        setFocusPinned(false);
      }
    },
    [video.videoElRef],
  );

  const { play, pause, seek, togglePlay, toggleMute, retry, setActiveTrack } = video;
  useImperativeHandle(
    ref,
    () => ({ play, pause, seek, toggleMute, toggleFullscreen }),
    [play, pause, seek, toggleMute, toggleFullscreen],
  );

  // With `onDoubleTap`, a single tap waits out the double-tap window before toggling (VP7).
  const handleTap = useDoubleTap(onDoubleTap, { onSingleTap: togglePlay });

  const stateForRender: VideoState = {
    ...video.state,
    duration: video.state.isLoaded ? video.state.duration : (durationHint ?? video.state.duration),
    isActive,
    dir,
    tracks,
    activeTrack: video.activeTrack,
    canFullscreen,
    isFullscreen,
    togglePlay,
    toggleMute,
    seek,
    retry,
    setActiveTrack,
    toggleFullscreen,
  };

  const context: VideoPlayerContextValue = {
    state: stateForRender,
    labels,
    locale,
    formatTime,
    seekStep,
    controlsVisible,
    wake,
    setMenuOpen,
  };

  const { videoElRef } = video;
  const seekBy = useCallback(
    (delta: number) => seek((videoElRef.current?.currentTime ?? 0) + delta),
    [seek, videoElRef],
  );

  return (
    <div
      ref={rootRef}
      dir={dirProp}
      className={cn("relative h-full w-full overflow-hidden bg-black", className)}
      onClick={onDoubleTap ? handleTap : undefined}
      onPointerMove={controls ? wake : undefined}
      onPointerDown={controls ? wake : undefined}
      onFocus={controls ? handleFocus : undefined}
      onBlur={controls ? handleBlur : undefined}
      onKeyDown={controls ? wake : undefined}
    >
      <VideoElement
        videoRef={video.videoRef}
        eventHandlers={video.videoEventHandlers}
        src={video.effectiveSrc}
        poster={poster}
        tracks={tracks}
        crossOrigin={crossOrigin}
        loop={loop}
        muted={muted}
        playsInline={playsInline}
        preload={preload}
        autoPlay={autoPlay}
        objectFit={objectFit}
        ariaLabel={labels.videoLabel}
        videoClassName={videoClassName}
        onClick={onDoubleTap ? undefined : togglePlay}
        onTogglePlay={togglePlay}
        onToggleMute={toggleMute}
        seekStep={controls ? seekStep : undefined}
        dir={dir}
        onSeekBy={seekBy}
      />

      {controls && (
        <VideoPlayerContext.Provider value={context}>
          {renderControls ? (
            renderControls(stateForRender)
          ) : (
            <DefaultControls
              showSeekBar={showSeekBar}
              showTime={showTime}
              showFullscreen={showFullscreen}
              controlsClassName={controlsClassName}
            />
          )}
        </VideoPlayerContext.Provider>
      )}
    </div>
  );
}

const VideoPlayer = memo(VideoPlayerInner);
VideoPlayer.displayName = "VideoPlayer";

export { VideoPlayer };
export default VideoPlayer;

export { default as VideoPlayer } from "./video-player";

export type {
  BufferedRange,
  ResolvedVideoPlayerLabels,
  VideoDirection,
  VideoPlayerHandle,
  VideoPlayerProps,
  VideoPlayerLabels,
  VideoProgress,
  VideoState,
  VideoTrack,
} from "./types";

export { DEFAULT_VIDEO_PLAYER_LABELS, defaultVideoPlayerLabels } from "./types";

// Flat parts — compose them inside `renderControls` for a lighter or custom overlay.
export { VideoPlayerPlayButton } from "./parts/play-button";
export { VideoPlayerMuteButton } from "./parts/mute-button";
export { VideoPlayerSeekBar } from "./parts/seek-bar";
export { VideoPlayerTime, VideoPlayerDurationBadge } from "./parts/time";
export { VideoPlayerFullscreenButton } from "./parts/fullscreen-button";
export { VideoPlayerCaptionsButton } from "./parts/captions-button";
export { VideoPlayerStatus } from "./parts/status";
export { useVideoPlayer, type VideoPlayerContextValue } from "./parts/video-player-context";

export {
  useDoubleTap,
  type UseDoubleTapOptions,
} from "./hooks/use-double-tap";

// @ilinxa/video-player 0.3.0

import type { ReactNode, Ref } from "react";

export interface VideoTrack {
  /** Track type. */
  kind: TextTrackKind;
  /** WebVTT URL. A cross-origin URL also needs `crossOrigin` on the player (and CORS on the server). */
  src: string;
  /** BCP-47 language tag (e.g. "en", "tr-TR"). */
  srcLang: string;
  /** Human-readable label, shown in the captions menu when there are several tracks. */
  label: string;
  /** Mark this track as default (only one per kind should be default). */
  default?: boolean;
}

/** One buffered span of the media, in seconds. */
export interface BufferedRange {
  start: number;
  end: number;
}

/** Media-time progress, from the element's own events (never a wall clock). */
export interface VideoProgress {
  currentTime: number;
  duration: number;
  buffered: BufferedRange[];
}

export type VideoDirection = "ltr" | "rtl";

export interface VideoState {
  /** Currently playing — mirrors the underlying `<video>` element. */
  isPlaying: boolean;
  /** Currently muted (the prop when `muted` is controlled). */
  isMuted: boolean;
  /** Active state from the `isActive` prop. */
  isActive: boolean;
  /** True after `loadedmetadata` fires. `duration` is reliable from this point. */
  isLoaded: boolean;
  /** Total duration in seconds (NaN until loaded, unless `durationHint` is set). */
  duration: number;
  /** Current playback position in seconds (rAF-throttled). */
  currentTime: number;
  /** True once playback has started for the current source (false = idle). */
  hasStarted: boolean;
  /** Waiting for data (`waiting` / `stalled`, or a URL refresh in flight). */
  isBuffering: boolean;
  /** The media failed and no refresh is coming — the error overlay shows. */
  hasError: boolean;
  /** Buffered spans, in seconds. */
  buffered: BufferedRange[];
  /** Resolved text direction. */
  dir: VideoDirection;
  /** Caption tracks (the `tracks` prop). */
  tracks: VideoTrack[];
  /** Index into `tracks` of the showing track, or `null` when captions are off. */
  activeTrack: number | null;
  /** True when a fullscreen API is available (resolved after mount). */
  canFullscreen: boolean;
  /** True while the player is fullscreen. */
  isFullscreen: boolean;
  /** Imperative: toggle play/pause. */
  togglePlay: () => void;
  /** Imperative: toggle mute/unmute (calls `onMutedChange` instead when `muted` is controlled). */
  toggleMute: () => void;
  /** Imperative: jump to `seconds` (clamped to the duration). */
  seek: (seconds: number) => void;
  /** Reload the current source after an error, resuming where it stopped. */
  retry: () => void;
  /** Show the track at `index`, or turn captions off with `null`. */
  setActiveTrack: (index: number | null) => void;
  /** Enter or leave fullscreen. */
  toggleFullscreen: () => void;
}

/** Imperative handle — pass `ref` to `<VideoPlayer>`. The `<video>` element itself is not exposed. */
export interface VideoPlayerHandle {
  /** Start playback. Resolves when playing; a browser refusal (autoplay policy) is swallowed. */
  play: () => Promise<void>;
  pause: () => void;
  /** Jump to `seconds` (clamped to the duration). */
  seek: (seconds: number) => void;
  toggleMute: () => void;
  /** Enter / leave fullscreen. Does nothing where no fullscreen API exists (`state.canFullscreen` is false). */
  toggleFullscreen: () => void;
}

/** Every label resolved — what the parts read. */
export interface ResolvedVideoPlayerLabels {
  /** aria-label on the play button. */
  play: string;
  /** aria-label on the pause button. */
  pause: string;
  /** aria-label on the mute toggle when audio is on. */
  mute: string;
  /** aria-label on the mute toggle when audio is muted. */
  unmute: string;
  /** aria-label on the `<video>` element itself. */
  videoLabel: string;
  /** aria-label on the seek bar. */
  seek: string;
  /** `aria-valuetext` on the seek bar. Receives seconds and the same values formatted. */
  position: (current: number, total: number, formatted: { current: string; total: string }) => string;
  /** Visible elapsed / total text. */
  timeDisplay: (current: string, total: string) => string;
  /** Accessible name of the idle duration badge. */
  durationBadge: (total: number, formatted: string) => string;
  /** aria-label on the fullscreen button. */
  fullscreen: string;
  /** aria-label on the fullscreen button while fullscreen. */
  exitFullscreen: string;
  /** aria-label on the captions toggle (one track). */
  captions: string;
  /** aria-label on the captions menu button (several tracks). */
  captionsMenu: string;
  /** The "off" item in the captions menu. */
  captionsOff: string;
  /** Accessible name of the buffering spinner. */
  buffering: string;
  /** Error overlay text. */
  error: string;
  /** Error overlay button. */
  retry: string;
}

/** Labels input: any subset; an `undefined` value never erases a default. */
export type VideoPlayerLabels = Partial<ResolvedVideoPlayerLabels>;

export interface VideoPlayerProps {
  /** Video URL. Required. A new `src` resets the player (and the `onMediaError` budget). */
  src: string;
  /** Poster image URL. Browser shows it before playback + on load failure. */
  poster?: string;
  /** Caption / subtitle tracks. Renders as `<track>` children and, when not empty, a captions control. */
  tracks?: VideoTrack[];
  /** Passed to `<video crossOrigin>` — needed for cross-origin caption files. Unset by default (a video served without CORS headers would fail with it). */
  crossOrigin?: "anonymous" | "use-credentials";

  // ─── Active state (carousel coordination) ────────────────────────
  /** When false, the video pauses and nothing starts it. Default: true. */
  isActive?: boolean;

  // ─── <video> attribute pass-through ──────────────────────────────
  /** Default: true — or false when `onEnded` is passed (otherwise `ended` could never fire). */
  loop?: boolean;
  /**
   * Default: true (autoplay-friendly; browsers block unmuted autoplay).
   * Controlled when `onMutedChange` is also passed: the prop wins on every render and the mute
   * button calls `onMutedChange` instead of changing the element. Without it, the user's toggle
   * applies until the prop next changes.
   */
  muted?: boolean;
  /** Receives the requested mute state. Makes `muted` controlled. */
  onMutedChange?: (muted: boolean) => void;
  /** Default: true (iOS Safari requires this for inline playback). */
  playsInline?: boolean;
  /** Default: "metadata". For long feeds pass "none" (+ `durationHint` for the idle badge). */
  preload?: "none" | "metadata" | "auto";
  /** Default: false. Subject to browser autoplay policy. */
  autoPlay?: boolean;
  /** Duration in seconds known ahead of loading (from your API) — shown by the idle badge until metadata loads. */
  durationHint?: number;

  // ─── Autoplay in view ────────────────────────────────────────────
  /** Play (muted) while at least `autoPlayThreshold` of the player is visible; pause when it leaves. Off under reduced motion. Default: false. */
  autoPlayInView?: boolean;
  /** Visibility ratio for `autoPlayInView`. Default: 0.5. */
  autoPlayThreshold?: number;
  /** At most one player per group plays: a player that starts pauses the others in its group. */
  autoplayGroup?: string;

  // ─── Visual ──────────────────────────────────────────────────────
  /** Object-fit for the video element. Default: "cover". */
  objectFit?: "cover" | "contain";
  /** Text direction. Default: the element's direction after mount, else "ltr". */
  dir?: VideoDirection;

  // ─── Controls ────────────────────────────────────────────────────
  /** Show control overlay (default OR custom). Default: true. With false: no overlay, no seek keys on the video. */
  controls?: boolean;
  /**
   * Custom control overlay. Receives full state + dispatchers. Rendered inside the player, so the
   * flat parts (`VideoPlayerSeekBar`, `VideoPlayerMuteButton`, …) work in it.
   */
  renderControls?: (state: VideoState) => ReactNode;
  /** Auto-hide controls after N ms during playback. Default: 2000. Pass 0 to disable. */
  controlsAutoHideMs?: number;
  /** Default controls: the seek bar. Default: true. */
  showSeekBar?: boolean;
  /** Default controls: elapsed / total time. Default: true. */
  showTime?: boolean;
  /** Default controls: a fullscreen button (hidden when no fullscreen API exists). Default: false. */
  showFullscreen?: boolean;
  /** Seconds per arrow-key step on the seek bar (and on the focused video). Default: 5. */
  seekStep?: number;

  // ─── Gestures ────────────────────────────────────────────────────
  /** Fires on a 300ms-window double-tap. A single tap then toggles playback after the window. */
  onDoubleTap?: () => void;

  // ─── Lifecycle callbacks ─────────────────────────────────────────
  onPlay?: () => void;
  onPause?: () => void;
  onEnded?: () => void;
  /** Throttled to one call per requestAnimationFrame max. */
  onTimeUpdate?: (currentTime: number, duration: number) => void;
  /** Media time + buffered spans; rAF-throttled, also on the `progress` event. */
  onProgress?: (progress: VideoProgress) => void;
  /** Fires on `loadedmetadata` — once per source load (again after a URL refresh or Retry). */
  onLoadedMetadata?: (duration: number) => void;
  /** Fires on every video element error. */
  onError?: (error: MediaError | null) => void;
  /**
   * Refresh an expired URL. Called once per `src`: a returned / resolved URL replaces the source
   * and playback resumes at the same time (and play state). A void answer, a rejection or a second
   * error shows the error overlay. While it is pending the player shows its buffering state.
   */
  onMediaError?: (src: string) => Promise<string | void> | string | void;

  // ─── i18n ────────────────────────────────────────────────────────
  /** Localized labels. Defaults are English. */
  labels?: VideoPlayerLabels;
  /** BCP-47 locale for time text. Default "en"; an invalid tag falls back to "en". */
  locale?: string;
  /** Override the time format (`m:ss` / `h:mm:ss` with `locale` digits by default). */
  formatDuration?: (seconds: number, locale: string) => string;

  // ─── Style overrides ─────────────────────────────────────────────
  /** Override classes for the wrapping <div>. */
  className?: string;
  /** Override classes for the <video> element. */
  videoClassName?: string;
  /** Override classes for the default control overlay. Ignored when `renderControls` is provided. */
  controlsClassName?: string;

  /** Imperative handle. */
  ref?: Ref<VideoPlayerHandle>;
}

/** Default English labels — exported for consumer composition. */
export const defaultVideoPlayerLabels: ResolvedVideoPlayerLabels = {
  play: "Play",
  pause: "Pause",
  mute: "Mute",
  unmute: "Unmute",
  videoLabel: "Video",
  seek: "Seek",
  position: (_current, _total, f) => `${f.current} of ${f.total}`,
  timeDisplay: (current, total) => `${current} / ${total}`,
  durationBadge: (_total, formatted) => `Duration ${formatted}`,
  fullscreen: "Full screen",
  exitFullscreen: "Exit full screen",
  captions: "Captions",
  captionsMenu: "Subtitles and captions",
  captionsOff: "Off",
  buffering: "Loading",
  error: "This video can't be played.",
  retry: "Retry",
};

/** @deprecated Use `defaultVideoPlayerLabels`. Kept as an alias for one minor. */
export const DEFAULT_VIDEO_PLAYER_LABELS: Required<VideoPlayerLabels> = defaultVideoPlayerLabels;

"use client";

import type { KeyboardEvent, ReactEventHandler, SyntheticEvent } from "react";
import { cn } from "@/lib/utils";
import type { VideoDirection, VideoTrack } from "../types";

interface VideoEventHandlers {
  onPlay: ReactEventHandler<HTMLVideoElement>;
  onPause: ReactEventHandler<HTMLVideoElement>;
  onEnded: ReactEventHandler<HTMLVideoElement>;
  onLoadedMetadata: ReactEventHandler<HTMLVideoElement>;
  onTimeUpdate: ReactEventHandler<HTMLVideoElement>;
  onProgress: ReactEventHandler<HTMLVideoElement>;
  onWaiting: ReactEventHandler<HTMLVideoElement>;
  onStalled: ReactEventHandler<HTMLVideoElement>;
  onPlaying: ReactEventHandler<HTMLVideoElement>;
  onCanPlay: ReactEventHandler<HTMLVideoElement>;
  onError: (e: SyntheticEvent<HTMLVideoElement>) => void;
  onVolumeChange: ReactEventHandler<HTMLVideoElement>;
}

interface VideoElementProps {
  videoRef: (node: HTMLVideoElement | null) => void;
  eventHandlers: VideoEventHandlers;
  src: string;
  poster?: string;
  tracks: VideoTrack[];
  crossOrigin?: "anonymous" | "use-credentials";
  loop: boolean;
  muted: boolean;
  playsInline: boolean;
  preload: "none" | "metadata" | "auto";
  autoPlay: boolean;
  objectFit: "cover" | "contain";
  ariaLabel: string;
  videoClassName?: string;
  /** Click on the video. Omitted when the player defers single taps for a double tap. */
  onClick?: () => void;
  onTogglePlay: () => void;
  /** Called for the M keyboard shortcut. */
  onToggleMute: () => void;
  /**
   * ← / → seek by this many seconds (direction-aware). Unset when the player renders no controls,
   * so a host's own arrow-key handling (story-viewer navigation) is never pre-empted.
   */
  seekStep?: number;
  dir: VideoDirection;
  onSeekBy: (delta: number) => void;
}

export function VideoElement({
  videoRef,
  eventHandlers,
  src,
  poster,
  tracks,
  crossOrigin,
  loop,
  muted,
  playsInline,
  preload,
  autoPlay,
  objectFit,
  ariaLabel,
  videoClassName,
  onClick,
  onTogglePlay,
  onToggleMute,
  seekStep,
  dir,
  onSeekBy,
}: VideoElementProps) {
  const handleKeyDown = (e: KeyboardEvent<HTMLVideoElement>) => {
    if (e.key === " " || e.code === "Space") {
      e.preventDefault();
      onTogglePlay();
    } else if (e.key === "m" || e.key === "M") {
      e.preventDefault();
      onToggleMute();
    } else if (seekStep && (e.key === "ArrowRight" || e.key === "ArrowLeft")) {
      // Handled here, so a carousel / viewer around the player ignores it (`defaultPrevented`).
      e.preventDefault();
      const forward = (e.key === "ArrowRight") === (dir === "ltr");
      onSeekBy(forward ? seekStep : -seekStep);
    }
  };

  return (
    <video
      ref={videoRef}
      src={src}
      poster={poster}
      crossOrigin={crossOrigin}
      loop={loop}
      muted={muted}
      playsInline={playsInline}
      preload={preload}
      autoPlay={autoPlay}
      tabIndex={0}
      aria-label={ariaLabel}
      onClick={onClick}
      onKeyDown={handleKeyDown}
      {...eventHandlers}
      className={cn(
        "h-full w-full cursor-pointer",
        objectFit === "cover" ? "object-cover" : "object-contain",
        videoClassName,
      )}
    >
      {tracks.map((t, i) => (
        <track
          key={`${t.kind}-${t.srcLang}-${i}`}
          kind={t.kind}
          src={t.src}
          srcLang={t.srcLang}
          label={t.label}
          default={t.default}
        />
      ))}
    </video>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { VideoPlayerCaptionsButton } from "./captions-button";
import { VideoPlayerFullscreenButton } from "./fullscreen-button";
import { VideoPlayerMuteButton } from "./mute-button";
import { VideoPlayerPlayButton } from "./play-button";
import { VideoPlayerSeekBar } from "./seek-bar";
import { VideoPlayerStatus } from "./status";
import { VideoPlayerDurationBadge, VideoPlayerTime } from "./time";
import { useVideoPlayer } from "./video-player-context";

interface DefaultControlsProps {
  showSeekBar: boolean;
  showTime: boolean;
  showFullscreen: boolean;
  controlsClassName?: string;
}

export function DefaultControls({
  showSeekBar,
  showTime,
  showFullscreen,
  controlsClassName,
}: DefaultControlsProps) {
  const { state, controlsVisible } = useVideoPlayer();
  const { isPlaying, hasStarted, hasError, isBuffering } = state;

  // Auto-hidden groups: fade out, and while hidden stay pointer-events-none so a click lands on the
  // video. Visible: only the interactive controls take pointer input — a tap on the time chip, the
  // duration badge or the spacer still reaches the video (play / pause, double tap).
  const fade = cn(
    "pointer-events-none motion-safe:transition-opacity motion-safe:duration-300",
    controlsVisible
      ? "opacity-100 [&_button]:pointer-events-auto [&_[role=slider]]:pointer-events-auto [&_[role=menu]]:pointer-events-auto"
      : "opacity-0",
  );

  return (
    <div className={cn("pointer-events-none absolute inset-0", controlsClassName)}>
      <VideoPlayerStatus />

      {!isPlaying && !hasError && !isBuffering && (
        <div className="absolute inset-0 flex items-center justify-center">
          <VideoPlayerPlayButton size="lg" className="pointer-events-auto" />
        </div>
      )}

      {/* The error overlay owns the frame — no controls over a failed video. */}
      {hasError ? null : !hasStarted ? (
        <>
          <div className={cn("absolute end-3 top-3", fade)}>
            <VideoPlayerDurationBadge />
          </div>
          <div className={cn("absolute end-3 bottom-(--video-player-controls-bottom,0.75rem)", fade)}>
            <VideoPlayerMuteButton />
          </div>
        </>
      ) : (
        <div className={cn("absolute inset-x-3 bottom-(--video-player-controls-bottom,0.75rem) flex items-center gap-2", fade)}>
          {isPlaying && <VideoPlayerPlayButton size="sm" />}
          {showSeekBar ? <VideoPlayerSeekBar className="flex-1" /> : <div className="flex-1" />}
          {showTime && <VideoPlayerTime />}
          <VideoPlayerCaptionsButton />
          {showFullscreen && <VideoPlayerFullscreenButton />}
          <VideoPlayerMuteButton />
        </div>
      )}
    </div>
  );
}

import { useCallback, useEffect, useLayoutEffect, useMemo, useReducer, useRef, useState } from "react";
import type { SyntheticEvent } from "react";
import type { BufferedRange, VideoProgress, VideoTrack } from "../types";
import { readBuffered } from "../lib/format";
import { useAutoplayGroup } from "./use-autoplay-group";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

interface VideoStateValue {
  isPlaying: boolean;
  isMuted: boolean;
  isLoaded: boolean;
  duration: number;
  currentTime: number;
  hasStarted: boolean;
  isBuffering: boolean;
  hasError: boolean;
  buffered: BufferedRange[];
}

type VideoAction =
  | { type: "play" }
  | { type: "pause" }
  | { type: "set-muted"; muted: boolean }
  /**
   * A new source starts loading. `resuming`: it replaces a failed one, and playback picks up where
   * it stopped. `buffering`: playback will restart, so show the loading state until it does.
   */
  | { type: "source"; resuming: boolean; buffering: boolean }
  | { type: "clear-error" }
  | { type: "loaded"; duration: number }
  | { type: "set-current-time"; currentTime: number }
  | { type: "buffered"; buffered: BufferedRange[] }
  | { type: "waiting" }
  | { type: "ready" }
  | { type: "error" }
  | { type: "recovering" }
  | { type: "ended" };

const initialState: VideoStateValue = {
  isPlaying: false,
  isMuted: true,
  isLoaded: false,
  duration: NaN,
  currentTime: 0,
  hasStarted: false,
  isBuffering: false,
  hasError: false,
  buffered: [],
};

const sameRanges = (a: BufferedRange[], b: BufferedRange[]) =>
  a.length === b.length && a.every((r, i) => r.start === b[i]!.start && r.end === b[i]!.end);

function videoReducer(state: VideoStateValue, action: VideoAction): VideoStateValue {
  switch (action.type) {
    case "play":
      return state.isPlaying && state.hasStarted && !state.hasError
        ? state
        : { ...state, isPlaying: true, hasStarted: true, hasError: false };
    case "pause":
      return state.isPlaying ? { ...state, isPlaying: false } : state;
    case "set-muted":
      return state.isMuted === action.muted ? state : { ...state, isMuted: action.muted };
    case "source":
      return action.resuming
        ? { ...initialState, isMuted: state.isMuted, hasStarted: state.hasStarted, isBuffering: action.buffering }
        : { ...initialState, isMuted: state.isMuted };
    case "clear-error":
      return state.hasError || state.isBuffering ? { ...state, hasError: false, isBuffering: false } : state;
    case "loaded":
      // Metadata is in: nothing is pending any more (a resumed play re-enters `waiting` if it must).
      return { ...state, isLoaded: true, duration: action.duration, isBuffering: false };
    case "set-current-time":
      return state.currentTime === action.currentTime
        ? state
        : { ...state, currentTime: action.currentTime };
    case "buffered":
      return sameRanges(state.buffered, action.buffered) ? state : { ...state, buffered: action.buffered };
    case "waiting":
      return state.isBuffering ? state : { ...state, isBuffering: true };
    case "ready":
      return state.isBuffering ? { ...state, isBuffering: false } : state;
    case "recovering":
      return { ...state, isBuffering: true, hasError: false };
    case "error":
      return { ...state, isBuffering: false, hasError: true, isPlaying: false };
    case "ended":
      return { ...state, isPlaying: false, currentTime: 0 };
    default:
      return state;
  }
}

/** `showing` for `index`, `hidden` for whichever track was showing (cues stay loaded). */
function showTrack(list: TextTrackList, index: number | null) {
  for (let i = 0; i < list.length; i++) {
    const track = list[i];
    if (!track) continue;
    if (i === index) track.mode = "showing";
    else if (track.mode === "showing") track.mode = "hidden";
  }
}

/** First `default` track, else none. */
const defaultTrackIndex = (tracks: VideoTrack[]) => {
  const i = tracks.findIndex((t) => t.default);
  return i === -1 ? null : i;
};

export interface UseVideoStateOptions {
  /** The host's `src`. */
  src: string;
  /** The `muted` prop. */
  muted: boolean;
  /** `muted` is controlled (an `onMutedChange` was passed). */
  onMutedChange?: (muted: boolean) => void;
  isActive: boolean;
  tracks: VideoTrack[];
  autoplayGroup?: string;
  /** Autoplay in view is on (and not disabled by reduced motion). */
  autoPlayInView: boolean;
  /** Visibility for autoplay: `null` = unknown (never starts or stops playback). */
  visible: boolean | null;
  onPlay?: () => void;
  onPause?: () => void;
  onEnded?: () => void;
  onTimeUpdate?: (currentTime: number, duration: number) => void;
  onProgress?: (progress: VideoProgress) => void;
  onLoadedMetadata?: (duration: number) => void;
  onError?: (error: MediaError | null) => void;
  onMediaError?: (src: string) => Promise<string | void> | string | void;
}

export function useVideoState(options: UseVideoStateOptions) {
  const { src, muted, isActive, tracks, autoplayGroup } = options;
  const mutedControlled = options.onMutedChange !== undefined;

  const [state, dispatch] = useReducer(videoReducer, { ...initialState, isMuted: muted });

  const videoElRef = useRef<HTMLVideoElement | null>(null);
  const videoRef = useCallback((node: HTMLVideoElement | null) => {
    videoElRef.current = node;
  }, []);

  // Latest options for the memoised handlers (no effect cascade on identity change).
  const optionsRef = useRef(options);
  const isActiveRef = useRef(isActive);
  useEffect(() => {
    optionsRef.current = options;
    isActiveRef.current = isActive;
  });

  // ─── Source: the host's `src`, or the URL `onMediaError` returned for it ─────────────────
  const [override, setOverride] = useState<{ for: string; src: string } | null>(null);
  const effectiveSrc = override && override.for === src ? override.src : src;
  const effectiveSrcRef = useRef(effectiveSrc);
  /** Host `src` values `onMediaError` was already asked about — once per `src` (C8). */
  const askedRef = useRef(new Set<string>());
  /** Where to pick up after an error: set at the error, consumed by the next `loadedmetadata`. */
  const resumeRef = useRef<{ time: number; play: boolean } | null>(null);
  /** Playing as far as the user is concerned — survives the `error` event. */
  const playingRef = useRef(false);
  /** A handler saw these events (so the mount check below does not repeat them). */
  const metadataSeenRef = useRef(false);
  const errorSeenRef = useRef(false);
  /** The URL the last `onMediaError` answer gave, and whether an answer is still pending. */
  const refreshUrlRef = useRef<string | null>(null);
  const pendingRef = useRef(false);

  useEffect(() => {
    if (effectiveSrcRef.current === effectiveSrc) return;
    effectiveSrcRef.current = effectiveSrc;
    // Resume only into the refreshed URL — or a URL that arrived while the refresh was pending (a
    // host such as media-carousel echoes the refreshed URL into `src`). Any other new `src` is
    // different media: it starts from 0, idle.
    const refreshed =
      resumeRef.current !== null && (pendingRef.current || effectiveSrc === refreshUrlRef.current);
    if (!refreshed) {
      resumeRef.current = null;
      playingRef.current = false;
    }
    dispatch({ type: "source", resuming: refreshed, buffering: refreshed && !!resumeRef.current?.play });
  }, [effectiveSrc]);

  // ─── Muted: controlled → the prop wins on every render ─────────────────────────────────
  useIsoLayoutEffect(() => {
    const el = videoElRef.current;
    if (mutedControlled && el && el.muted !== muted) el.muted = muted;
  });
  const isMuted = mutedControlled ? muted : state.isMuted;

  // rAF cleanup on unmount.
  const rafRef = useRef<number | null>(null);
  useEffect(() => {
    return () => {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  // Pause when isActive flips false. Hook owns video DOM, single dep.
  useEffect(() => {
    if (!isActive) videoElRef.current?.pause();
  }, [isActive]);

  const pause = useCallback(() => {
    videoElRef.current?.pause();
  }, []);
  const claimGroup = useAutoplayGroup(autoplayGroup, pause);

  const play = useCallback(async () => {
    const el = videoElRef.current;
    if (!el) return;
    try {
      await el.play();
    } catch {
      // Browser autoplay policy may reject; a user gesture is required.
    }
  }, []);

  const report = useCallback((el: HTMLVideoElement) => {
    const buffered = readBuffered(el);
    dispatch({ type: "buffered", buffered });
    optionsRef.current.onProgress?.({ currentTime: el.currentTime, duration: el.duration, buffered });
  }, []);

  // ─── Media event handlers ───────────────────────────────────────────────────────────────
  const handleVideoPlay = useCallback(() => {
    playingRef.current = true;
    dispatch({ type: "play" });
    claimGroup();
    optionsRef.current.onPlay?.();
  }, [claimGroup]);

  const handleVideoPause = useCallback(() => {
    playingRef.current = false;
    dispatch({ type: "pause" });
    optionsRef.current.onPause?.();
  }, []);

  const handleVideoEnded = useCallback(() => {
    playingRef.current = false;
    dispatch({ type: "ended" });
    optionsRef.current.onEnded?.();
  }, []);

  const handleVideoLoadedMetadata = useCallback(() => {
    const el = videoElRef.current;
    if (!el) return;
    metadataSeenRef.current = true;
    dispatch({ type: "loaded", duration: el.duration });
    optionsRef.current.onLoadedMetadata?.(el.duration);
    const resume = resumeRef.current;
    if (!resume) return;
    resumeRef.current = null;
    if (resume.time > 0 && (!Number.isFinite(el.duration) || resume.time < el.duration)) {
      el.currentTime = resume.time;
      dispatch({ type: "set-current-time", currentTime: resume.time });
    }
    if (resume.play && isActiveRef.current) void el.play().catch(() => {});
  }, []);

  const handleVideoTimeUpdate = useCallback(() => {
    if (rafRef.current !== null) return;
    rafRef.current = requestAnimationFrame(() => {
      rafRef.current = null;
      const el = videoElRef.current;
      if (!el) return;
      dispatch({ type: "set-current-time", currentTime: el.currentTime });
      optionsRef.current.onTimeUpdate?.(el.currentTime, el.duration);
      report(el);
    });
  }, [report]);

  const handleVideoProgress = useCallback(() => {
    const el = videoElRef.current;
    if (el) report(el);
  }, [report]);

  const handleVideoWaiting = useCallback(() => dispatch({ type: "waiting" }), []);
  const handleVideoReady = useCallback(() => dispatch({ type: "ready" }), []);

  /** The media failed: report it, remember where to resume, and ask `onMediaError` once per `src`. */
  const failWith = useCallback((el: HTMLVideoElement) => {
    errorSeenRef.current = true;
    const opts = optionsRef.current;
    opts.onError?.(el.error);
    if (!resumeRef.current) {
      resumeRef.current = { time: el.currentTime || 0, play: playingRef.current };
    }
    const host = opts.src;
    const handler = opts.onMediaError;
    if (!handler || askedRef.current.has(host)) {
      dispatch({ type: "error" });
      return;
    }
    askedRef.current.add(host);
    pendingRef.current = true;
    dispatch({ type: "recovering" });
    const failed = effectiveSrcRef.current;
    const apply = (next: string | void) => {
      pendingRef.current = false;
      // The host moved on while we waited (or echoed the refreshed URL itself): its `src` owns
      // the player now.
      if (optionsRef.current.src !== host) return;
      if (typeof next === "string" && next && next !== failed) {
        refreshUrlRef.current = next;
        setOverride({ for: host, src: next });
      } else {
        dispatch({ type: "error" });
      }
    };
    try {
      const result = handler(failed);
      if (result && typeof (result as Promise<unknown>).then === "function") {
        (result as Promise<string | void>).then(apply, () => apply(undefined));
      } else {
        apply(result as string | void);
      }
    } catch {
      // A throwing handler is a failed refresh: show the error, never ask again for this `src`.
      apply(undefined);
    }
  }, []);

  const handleVideoError = useCallback(
    (e: SyntheticEvent<HTMLVideoElement>) => failWith(e.currentTarget),
    [failWith],
  );

  // A server-rendered `<video>` starts loading before hydration, and events it fired before React
  // attached its handlers are lost: metadata (→ no duration, no seek bar), an error (→ an expired
  // URL never reaches `onMediaError`), `autoPlay`'s play. Read the element once on mount instead.
  useEffect(() => {
    const el = videoElRef.current;
    if (!el) return;
    if (el.error && !errorSeenRef.current) {
      failWith(el);
      return;
    }
    if (el.readyState >= 1 && !metadataSeenRef.current) handleVideoLoadedMetadata();
    if (!el.paused) handleVideoPlay();
  }, [failWith, handleVideoLoadedMetadata, handleVideoPlay]);

  const handleVideoVolumeChange = useCallback(() => {
    const el = videoElRef.current;
    if (!el) return;
    dispatch({ type: "set-muted", muted: el.muted });
  }, []);

  const videoEventHandlers = useMemo(
    () => ({
      onPlay: handleVideoPlay,
      onPause: handleVideoPause,
      onEnded: handleVideoEnded,
      onLoadedMetadata: handleVideoLoadedMetadata,
      onTimeUpdate: handleVideoTimeUpdate,
      onProgress: handleVideoProgress,
      onWaiting: handleVideoWaiting,
      onStalled: handleVideoWaiting,
      onPlaying: handleVideoReady,
      onCanPlay: handleVideoReady,
      onError: handleVideoError,
      onVolumeChange: handleVideoVolumeChange,
    }),
    [
      handleVideoPlay,
      handleVideoPause,
      handleVideoEnded,
      handleVideoLoadedMetadata,
      handleVideoTimeUpdate,
      handleVideoProgress,
      handleVideoWaiting,
      handleVideoReady,
      handleVideoError,
      handleVideoVolumeChange,
    ],
  );

  // ─── Commands ───────────────────────────────────────────────────────────────────────────
  const togglePlay = useCallback(() => {
    const el = videoElRef.current;
    if (!el) return;
    if (el.paused) {
      void el.play().catch(() => {
        // Browser autoplay policy may reject; user gesture is required.
      });
    } else {
      el.pause();
    }
  }, []);

  const toggleMute = useCallback(() => {
    const el = videoElRef.current;
    const opts = optionsRef.current;
    if (opts.onMutedChange) {
      opts.onMutedChange(!opts.muted);
      return;
    }
    if (!el) return;
    el.muted = !el.muted;
    // Browsers also fire `volumechange`; dispatching here keeps environments that don't in sync.
    dispatch({ type: "set-muted", muted: el.muted });
  }, []);

  const seek = useCallback((seconds: number) => {
    const el = videoElRef.current;
    if (!el || !Number.isFinite(seconds)) return;
    const max = Number.isFinite(el.duration) ? el.duration : Infinity;
    const next = Math.min(Math.max(0, seconds), max);
    el.currentTime = next;
    dispatch({ type: "set-current-time", currentTime: next });
  }, []);

  const retry = useCallback(() => {
    const el = videoElRef.current;
    if (!el) return;
    if (!resumeRef.current) resumeRef.current = { time: el.currentTime || 0, play: playingRef.current };
    el.load();
    if (resumeRef.current.play && isActiveRef.current) {
      dispatch({ type: "recovering" });
      // `play()` also loads under `preload="none"`, where `load()` alone fetches nothing.
      void el.play().catch(() => {});
    } else {
      // Paused / idle: drop the overlay; the time is restored when metadata loads (or on play).
      dispatch({ type: "clear-error" });
    }
  }, []);

  // ─── Autoplay in view (VP5) ─────────────────────────────────────────────────────────────
  const { autoPlayInView, visible } = options;
  useEffect(() => {
    if (!autoPlayInView || visible === null) return;
    const el = videoElRef.current;
    if (!el) return;
    if (!visible) {
      el.pause();
      return;
    }
    if (!isActive) return;
    const opts = optionsRef.current;
    // Browsers allow muted autoplay only — unless the host controls `muted` to false.
    if (!(opts.onMutedChange && !opts.muted) && !el.muted) {
      el.muted = true;
      if (!opts.onMutedChange) dispatch({ type: "set-muted", muted: true });
    }
    void el.play().catch(() => {});
  }, [autoPlayInView, visible, isActive]);

  // ─── Captions ───────────────────────────────────────────────────────────────────────────
  const tracksKey = tracks.map((t) => `${t.kind}\u0000${t.srcLang}\u0000${t.src}`).join("\u0001");
  const [trackState, setTrackState] = useState<{ key: string; active: number | null }>(() => ({
    key: tracksKey,
    active: defaultTrackIndex(tracks),
  }));
  const activeTrack = trackState.key === tracksKey ? trackState.active : defaultTrackIndex(tracks);

  const setActiveTrack = useCallback(
    (index: number | null) => {
      const list = videoElRef.current?.textTracks;
      if (list) showTrack(list, index);
      setTrackState({ key: tracksKey, active: index });
    },
    [tracksKey],
  );

  // A track switched on elsewhere (the browser's own fullscreen menu) — follow it.
  useEffect(() => {
    const list = videoElRef.current?.textTracks;
    if (!list || typeof list.addEventListener !== "function") return;
    const onChange = () => {
      let showing: number | null = null;
      for (let i = 0; i < list.length; i++) if (list[i]?.mode === "showing") showing = i;
      setTrackState({ key: tracksKey, active: showing });
    };
    list.addEventListener("change", onChange);
    return () => list.removeEventListener("change", onChange);
  }, [tracksKey]);

  return {
    state: { ...state, isMuted },
    activeTrack,
    effectiveSrc,
    videoElRef,
    videoRef,
    videoEventHandlers,
    play,
    pause,
    togglePlay,
    toggleMute,
    seek,
    retry,
    setActiveTrack,
  };
}

import { useCallback, useEffect, useRef } from "react";
import type { MouseEvent } from "react";

export interface UseDoubleTapOptions {
  /** Time window in ms within which a second tap counts as a double-tap. Default: 300. */
  windowMs?: number;
  /**
   * Called for a tap that turned out NOT to be a double tap — `windowMs` after it, once no second
   * tap came. Without it, a single tap is silent (the pre-0.3 behaviour, unchanged).
   */
  onSingleTap?: () => void;
}

const INTERACTIVE_SELECTOR =
  'button, a, input, select, textarea, [role="button"], [role="slider"], [role="menuitemradio"]';

/**
 * True when the event target sits inside an interactive control that lives
 * between the handler's element (`currentTarget`) and the target itself.
 */
function isFromInteractiveControl(event: MouseEvent<HTMLElement>): boolean {
  const target = event.target;
  const boundary = event.currentTarget;
  if (!(target instanceof Element) || !boundary) return false;
  const control = target.closest(INTERACTIVE_SELECTOR);
  return control !== null && control !== boundary && boundary.contains(control);
}

/**
 * Returns a click handler that fires `onDoubleTap` only when invoked twice
 * within `windowMs` of each other. Single-tap is silent unless `onSingleTap` is
 * given, in which case it fires once the window passes without a second tap.
 * After firing, the timestamp resets so a triple-tap doesn't fire again.
 *
 * Clicks whose target is inside an interactive control (button, a, input,
 * select, textarea, `[role="button"]`, `[role="slider"]`, `[role="menuitemradio"]`)
 * are ignored: they neither fire nor arm the double-tap window, so two quick
 * taps on a control never read as a "like".
 *
 * Reusable outside `<video>` contexts — image double-tap-to-like, card
 * double-tap-to-favorite, etc.
 */
export function useDoubleTap(
  onDoubleTap: (() => void) | undefined,
  options?: UseDoubleTapOptions,
): React.MouseEventHandler<HTMLElement> {
  // -Infinity, not 0: `performance.now()` starts at 0, so a first tap within `windowMs` of page
  // load would otherwise read as the second half of a double tap.
  const lastTapRef = useRef(Number.NEGATIVE_INFINITY);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const windowMs = options?.windowMs ?? 300;
  const onSingleTapRef = useRef(options?.onSingleTap);
  useEffect(() => {
    onSingleTapRef.current = options?.onSingleTap;
  });
  useEffect(
    () => () => {
      if (timerRef.current !== null) clearTimeout(timerRef.current);
    },
    [],
  );

  return useCallback(
    // `event` is optional so the handler can still be called manually (`tap()`).
    (event?: MouseEvent<HTMLElement>) => {
      if (!onDoubleTap) return;
      if (event && isFromInteractiveControl(event)) return;
      const now = performance.now();
      if (now - lastTapRef.current < windowMs) {
        if (timerRef.current !== null) {
          clearTimeout(timerRef.current);
          timerRef.current = null;
        }
        onDoubleTap();
        lastTapRef.current = Number.NEGATIVE_INFINITY;
      } else {
        lastTapRef.current = now;
        if (onSingleTapRef.current) {
          if (timerRef.current !== null) clearTimeout(timerRef.current);
          timerRef.current = setTimeout(() => {
            timerRef.current = null;
            onSingleTapRef.current?.();
          }, windowMs);
        }
      }
    },
    [onDoubleTap, windowMs],
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * Players by group name. Shared across instances ON PURPOSE — "at most one player per group
 * plays" is a cross-instance rule. Each entry is that player's own `pause`; an unmounted player
 * removes itself, and an empty group is deleted, so nothing outlives the players that use it.
 */
const groups = new Map<string, Set<() => void>>();

/**
 * Joins `group` (when set) and returns `claim()`: call it when this player starts playing — every
 * other player in the group pauses.
 */
export function useAutoplayGroup(group: string | undefined, pause: () => void): () => void {
  const pauseRef = useRef(pause);
  useEffect(() => {
    pauseRef.current = pause;
  });
  // One stable function per mount, so the Set entry is removable.
  const [member] = useState(() => () => pauseRef.current());

  useEffect(() => {
    if (!group) return;
    let set = groups.get(group);
    if (!set) groups.set(group, (set = new Set()));
    set.add(member);
    return () => {
      set.delete(member);
      if (set.size === 0 && groups.get(group) === set) groups.delete(group);
    };
  }, [group, member]);

  return useCallback(() => {
    if (!group) return;
    for (const other of groups.get(group) ?? []) if (other !== member) other();
  }, [group, member]);
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * Auto-hide for the control overlay (VP6). Always visible while paused, with auto-hide disabled
 * (`autoHideMs <= 0`), under reduced motion, or while `pinned` (keyboard focus inside the
 * controls, an open menu) — a keyboard user never ends up acting on an invisible control.
 * While playing, `wake()` (pointer movement, a tap, focus or a key anywhere in the player) shows
 * the controls and re-arms the timer. Every play / pause transition shows them again.
 *
 * The timer lives in a ref: `wake()` at pointer-event rate re-renders only when the controls
 * were actually hidden.
 */
export function useControlsVisibility(
  isPlaying: boolean,
  autoHideMs: number,
  reducedMotion: boolean,
  pinned: boolean,
) {
  const alwaysVisible = !isPlaying || autoHideMs <= 0 || reducedMotion || pinned;
  const [hidden, setHidden] = useState(false);
  const [lastPlaying, setLastPlaying] = useState(isPlaying);
  if (lastPlaying !== isPlaying) {
    setLastPlaying(isPlaying);
    setHidden(false);
  }

  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const armRef = useRef<() => void>(() => {});

  useEffect(() => {
    const clear = () => {
      if (timerRef.current !== null) clearTimeout(timerRef.current);
      timerRef.current = null;
    };
    armRef.current = alwaysVisible
      ? clear
      : () => {
          clear();
          timerRef.current = setTimeout(() => setHidden(true), autoHideMs);
        };
    armRef.current();
    return clear;
  }, [alwaysVisible, autoHideMs, isPlaying]);

  const wake = useCallback(() => {
    setHidden(false);
    armRef.current();
  }, []);

  return { visible: alwaysVisible || !hidden, wake };
}

"use client";

import { useEffect, useLayoutEffect, useState } from "react";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type Direction = "ltr" | "rtl";

/**
 * Resolves text direction (consumer contract C4 / R6): the `dir` prop wins; otherwise the
 * element's direction, read after mount — the computed `direction`, or the nearest explicit
 * non-`auto` `[dir]` ancestor (jsdom has no UA stylesheet for `dir`); otherwise `"ltr"`.
 *
 * The server render and the first client render both return the prop or `"ltr"`, so markup
 * must not depend on the resolved value before mount. Key handling, swipe, carousel and
 * transition logic may. A later direction change is not observed — pass `dir` if the app
 * switches direction at runtime without remounting.
 *
 * Directional props take `"start" | "end"`; physical values stay only as deprecated aliases.
 * Copy into a component's `hooks/`. Canonical copy: `_template/_snippets/` (tests next to it).
 */
export function useDirection(
  ref: React.RefObject<HTMLElement | null>,
  dirProp?: Direction,
): Direction {
  const [resolved, setResolved] = useState<Direction>("ltr");
  useIsoLayoutEffect(() => {
    if (dirProp) return;
    const el = ref.current;
    if (!el) return;
    const explicit = el.closest('[dir]:not([dir="auto"])')?.getAttribute("dir")?.toLowerCase();
    const rtl = getComputedStyle(el).direction === "rtl" || explicit === "rtl";
    setResolved(rtl ? "rtl" : "ltr");
  }, [dirProp, ref]);
  return dirProp ?? resolved;
}

"use client";

import { useEffect, useState, useSyncExternalStore } from "react";

const REDUCED_MOTION = "(prefers-reduced-motion: reduce)";

const hasMatchMedia = () => typeof window !== "undefined" && typeof window.matchMedia === "function";

function subscribeReducedMotion(onChange: () => void) {
  if (!hasMatchMedia()) return () => {};
  const mq = window.matchMedia(REDUCED_MOTION);
  mq.addEventListener("change", onChange);
  return () => mq.removeEventListener("change", onChange);
}

const readReducedMotion = () => hasMatchMedia() && window.matchMedia(REDUCED_MOTION).matches;
const serverFalse = () => false;
const STEPS = Array.from({ length: 21 }, (_, i) => i / 20);

/**
 * True under `prefers-reduced-motion: reduce`. `false` on the server, on the hydrating render and
 * wherever `matchMedia` does not exist (it is guarded, not assumed — jsdom has none).
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribeReducedMotion, readReducedMotion, serverFalse);
}

/**
 * Whether at least `threshold` of the element is visible. `null` until the first observation, and
 * always `null` when disabled or where IntersectionObserver does not exist — "unknown" never
 * starts or stops playback.
 */
export function useVisibility(
  ref: React.RefObject<HTMLElement | null>,
  threshold: number,
  enabled: boolean,
): boolean | null {
  const [visible, setVisible] = useState<boolean | null>(null);
  useEffect(() => {
    const el = ref.current;
    if (!enabled || !el || typeof IntersectionObserver === "undefined") {
      setVisible(null);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[entries.length - 1];
        if (!entry) return;
        // A player taller than the viewport may never reach the ratio: covering at least
        // `threshold` of the viewport counts as visible (same rule as media-carousel).
        const viewport = entry.rootBounds?.height ?? 0;
        const coversViewport =
          viewport > 0 && (entry.intersectionRect?.height ?? 0) >= viewport * threshold;
        setVisible(entry.isIntersecting && (entry.intersectionRatio >= threshold || coversViewport));
      },
      { threshold: STEPS },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref, threshold, enabled]);
  return visible;
}

"use client";

import { useCallback, useEffect, useState } from "react";

/** iOS Safari exposes fullscreen on the `<video>` only. */
type WebkitVideo = HTMLVideoElement & { webkitEnterFullscreen?: () => void };

/**
 * Fullscreen for the player: the container's `requestFullscreen`, else the `<video>`'s
 * `webkitEnterFullscreen` (iOS). `canFullscreen` is resolved after mount (false on the server and
 * the hydrating render), so the button never appears and vanishes on hydration.
 */
export function useFullscreen(
  containerRef: React.RefObject<HTMLElement | null>,
  videoRef: React.RefObject<HTMLVideoElement | null>,
) {
  const [canFullscreen, setCanFullscreen] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);

  useEffect(() => {
    const container = containerRef.current;
    const video = videoRef.current as WebkitVideo | null;
    const standard =
      !!container &&
      typeof container.requestFullscreen === "function" &&
      document.fullscreenEnabled !== false;
    setCanFullscreen(standard || typeof video?.webkitEnterFullscreen === "function");

    const onChange = () =>
      setIsFullscreen(!!container && document.fullscreenElement === container);
    const onBegin = () => setIsFullscreen(true);
    const onEnd = () => setIsFullscreen(false);
    document.addEventListener("fullscreenchange", onChange);
    video?.addEventListener("webkitbeginfullscreen", onBegin);
    video?.addEventListener("webkitendfullscreen", onEnd);
    return () => {
      document.removeEventListener("fullscreenchange", onChange);
      video?.removeEventListener("webkitbeginfullscreen", onBegin);
      video?.removeEventListener("webkitendfullscreen", onEnd);
    };
  }, [containerRef, videoRef]);

  const toggleFullscreen = useCallback(() => {
    const container = containerRef.current;
    const video = videoRef.current as WebkitVideo | null;
    if (container && document.fullscreenElement === container) {
      void document.exitFullscreen?.().catch(() => {});
      return;
    }
    if (container && typeof container.requestFullscreen === "function") {
      void Promise.resolve(container.requestFullscreen()).catch(() => {
        // Refused (not from a user gesture, or blocked by a permissions policy).
      });
      return;
    }
    video?.webkitEnterFullscreen?.();
  }, [containerRef, videoRef]);

  return { canFullscreen, isFullscreen, toggleFullscreen };
}

import {
  defaultVideoPlayerLabels,
  type ResolvedVideoPlayerLabels,
  type VideoPlayerLabels,
} from "../types";

/** Merge `labels` over the defaults — an `undefined` value never erases a default (C2). */
export function resolveLabels(labels: VideoPlayerLabels | undefined): ResolvedVideoPlayerLabels {
  const out: ResolvedVideoPlayerLabels = { ...defaultVideoPlayerLabels };
  if (!labels) return out;
  for (const key of Object.keys(labels) as (keyof ResolvedVideoPlayerLabels)[]) {
    const value = labels[key];
    if (value !== undefined) (out as unknown as Record<string, unknown>)[key] = value;
  }
  return out;
}

/**
 * A valid BCP 47 tag for `locale`, else `"en"`. An invalid tag (`"en_US"` from an i18n library)
 * makes `Intl` throw — that must not take down the render.
 */
export function resolveLocale(locale: string | undefined): string {
  if (!locale) return "en";
  try {
    return Intl.getCanonicalLocales(locale)[0] ?? "en";
  } catch {
    return "en";
  }
}

/**
 * The default duration format: `m:ss`, or `h:mm:ss` from one hour, with the locale's digits.
 * NaN / negative / infinite (a live stream) read as 0. Create it inside the component, memoised
 * on `locale` (C3) — never at module scope.
 */
export function createDurationFormatter(locale: string): (seconds: number) => string {
  const pad = new Intl.NumberFormat(locale, { minimumIntegerDigits: 2, useGrouping: false });
  const plain = new Intl.NumberFormat(locale, { useGrouping: false });
  return (seconds) => {
    const total = Number.isFinite(seconds) && seconds > 0 ? Math.floor(seconds) : 0;
    const h = Math.floor(total / 3600);
    const m = Math.floor((total % 3600) / 60);
    const s = total % 60;
    return h > 0
      ? `${plain.format(h)}:${pad.format(m)}:${pad.format(s)}`
      : `${plain.format(m)}:${pad.format(s)}`;
  };
}

/** `el.buffered` as plain ranges (jsdom and some browsers throw or return nothing). */
export function readBuffered(el: HTMLMediaElement): { start: number; end: number }[] {
  const out: { start: number; end: number }[] = [];
  try {
    const ranges = el.buffered;
    if (!ranges) return out;
    for (let i = 0; i < ranges.length; i++) out.push({ start: ranges.start(i), end: ranges.end(i) });
  } catch {
    // not implemented — no ranges
  }
  return out;
}

"use client";

import { createContext, useContext } from "react";
import type { ResolvedVideoPlayerLabels, VideoState } from "../types";

export interface VideoPlayerContextValue {
  state: VideoState;
  labels: ResolvedVideoPlayerLabels;
  /** Resolved locale (`"en"` for an invalid tag). */
  locale: string;
  /** `formatDuration` bound to the locale. */
  formatTime: (seconds: number) => string;
  /** Seconds per arrow-key step. */
  seekStep: number;
  /** The overlay is showing (auto-hide). Hidden controls must not take pointer input. */
  controlsVisible: boolean;
  /** Show the controls and re-arm auto-hide. */
  wake: () => void;
  /** A part's popup (the captions menu) opened / closed — auto-hide waits while one is open. */
  setMenuOpen: (open: boolean) => void;
}

export const VideoPlayerContext = createContext<VideoPlayerContextValue | null>(null);

/**
 * The player's state, labels and formatters — for the flat parts (`VideoPlayerSeekBar`, …),
 * which render inside `<VideoPlayer>` (its default controls, or your `renderControls`).
 */
export function useVideoPlayer(): VideoPlayerContextValue {
  const ctx = useContext(VideoPlayerContext);
  if (!ctx) {
    throw new Error("VideoPlayer parts must render inside <VideoPlayer> (default controls or renderControls).");
  }
  return ctx;
}

